mapper.select:

WHERE s.site_code = #{siteCode}
  AND s.use_yn = 'Y'
  AND s.delete_yn = 'N'

SELECT COUNT(*) FROM tb_site
WHERE site_code = #{siteCode}
  AND delete_yn = 'N'

    AND site_id <> #{excludeId}

SELECT COALESCE(sel.layout_code, def.layout_code) AS layout_code,
       t.template_code AS template_code
FROM (SELECT 1 AS one) dummy
LEFT JOIN tb_layout   sel ON sel.layout_id   = #{layoutId}
LEFT JOIN tb_template t   ON t.template_id   = #{templateId}
LEFT JOIN tb_layout   def ON def.layout_id   = t.default_layout_id
